class Solution {
    public int MaxSumIncreasingSubsequence(int[] arr, int n) {

        // Raj Thomas 20th May 2026 11:34PM IST
        int[] dp = new int[arr.Length];
        int max = 0;

        for(int i = 0; i < arr.Length; i++) {
            dp[i] = arr[i];

            for(int j = 0; j < i; j++) {

                if(arr[j] < arr[i]) {
                    dp[i] = Math.Max(dp[i], dp[j] + arr[i]);
                }
            }

            max = Math.Max(max, dp[i]);
        }

        return max;
    }
}
```

